"""Independent analytic check of composite plastic capacities for the fixture.

Straightforward plastic stress block calculation:
 - locate the plastic neutral axis (PNA) where sum(f_y * A) above equals below
 - Mp = sum(f_y * A * |distance from PNA to each material block force centroid|)
"""
from __future__ import annotations

import json
from pathlib import Path

fixture = json.loads(Path("fixtures/hybrid_section.json").read_text())

mats = {m["id"]: m for m in fixture["materials"]}
# rectangles: (x0, x1, y0, y1, f_y)
rects = []
for r in fixture["regions"]:
    fy = mats[r["material"]]["yield_strength"]
    rects.append((r["x"], r["x"] + r["width"], r["y"], r["y"] + r["depth"], fy))


def pna_and_mp(direction: str) -> tuple[float, float]:
    total = sum(fy * (x1 - x0) * (y1 - y0) for x0, x1, y0, y1, fy in rects)
    half = total / 2
    # sweep slices of unit thickness along the sweep axis
    acc = 0.0
    pos = 0.0
    if direction == "x":  # bending about x -> sweep in y
        bounds = sorted({y0 for x0, x1, y0, y1, fy in rects} | {y1 for x0, x1, y0, y1, fy in rects})
    else:  # bending about y -> sweep in x
        bounds = sorted({x0 for x0, x1, y0, y1, fy in rects} | {x1 for x0, x1, y0, y1, fy in rects})
    for a, b in zip(bounds[:-1], bounds[1:]):
        strip = 0.0
        for x0, x1, y0, y1, fy in rects:
            if direction == "x":
                if y0 <= a and b <= y1:
                    strip += fy * (x1 - x0) * (b - a)
            else:
                if x0 <= a and b <= x1:
                    strip += fy * (y1 - y0) * (b - a)
        if acc + strip >= half:
            pos = a + (half - acc) * (b - a) / strip
            acc = half
            break
        acc += strip
        pos = b
    # Mp = sum over pieces of fy*A*|c - pos|
    mp = 0.0
    for x0, x1, y0, y1, fy in rects:
        for lo, hi in ((x0, x1) if direction == "y" else (y0, y1),):
            pass
        segs = []
        if direction == "x":
            segs = [(y0, min(y1, pos)), (max(y0, pos), y1)]
        else:
            segs = [(x0, min(x1, pos)), (max(x0, pos), x1)]
        for a, b in segs:
            if b > a:
                if direction == "x":
                    area = (x1 - x0) * (b - a)
                else:
                    area = (y1 - y0) * (b - a)
                mp += fy * area * abs((a + b) / 2 - pos)
    return pos, mp


for d in ("x", "y"):
    pna, mp = pna_and_mp(d)
    print(f"bending about {d}: PNA = {pna:.6f}, Mp = {mp:.1f}")

